import {readFileSync} from 'node:fs';
import {qtcScript} from '../../src/pq/qtc-transaction.js';
import {decodeQtcPrevoutTransaction} from '../../src/pq/qtc-prevout.js';
export function qtcGatewayFixture({count=1,value=200000000n}={}){
 const vector=JSON.parse(readFileSync(new URL('./pq-receive.json',import.meta.url))).vectors[0],address=vector.addresses.qtc.mainnet,script=qtcScript(address),u64=v=>{let s='';for(let i=0;i<8;i++){s+=Number(v&255n).toString(16).padStart(2,'0');v>>=8n;}return s;},raw='0200000001'+'00'.repeat(32)+'ffffffff0100ffffffff'+count.toString(16).padStart(2,'0')+(u64(value)+'22'+script).repeat(count)+'00000000',prev=decodeQtcPrevoutTransaction(raw),tip='ab'.repeat(32),calls=[];
 const state={raw,previousTxid:prev.txid,chain:{chain:'main',hash:tip,height:'200',node_height:'200',indexer_lag:'0',time:String(Math.floor(Date.now()/1000))},utxos:Array.from({length:count},(_,vout)=>({txid:prev.txid,vout:String(vout),value:String(value),height:'100',confirmations:'101',script_pubkey:script,coinbase:true})),postStatus:200,responseHash:null,signedRaw:null,status:null,block:null};
 const fetcher=async(url,o={})=>{calls.push({url,method:o.method??'GET',body:o.body});if(url==='https://qtc.events/api/v1/tx/broadcast'&&o.method==='POST'){state.signedRaw=JSON.parse(o.body).hex;const txid=decodeQtcPrevoutTransaction(state.signedRaw).txid;return new Response(JSON.stringify(state.postStatus===200?{txid:state.responseHash??txid}:{error:{code:'unresolved',message:'fixture'}}),{status:state.postStatus});}
 let data;if(url.endsWith('/chain'))data=state.chain;else if(url.endsWith('/block/0'))data={block:{height:'0',hash:'d5f04a8a320b4e7bb454c7c564ca9cf191f70d7521d2486b62274df776f4eb24'}};else if(url.endsWith('/fees'))data={unit:'atoms_per_byte',1:'2',3:'2',6:'2',12:'2'};else if(url.includes('/utxo?'))data={address,script_pubkey:script,tip_height:'200',total:String(state.utxos.length),utxos:state.utxos};else if(url.endsWith('/hex'))return new Response(url.includes(prev.txid)?state.raw:state.signedRaw??'',{status:200});else if(url.endsWith('/status'))return new Response(JSON.stringify(state.status??{}),{status:state.status?200:404});else if(url.includes('/block/'))data=state.block;else if(url===`https://qtc.events/api/v1/tx/${prev.txid}`)data={txid:prev.txid,height:'100',confirmations:'101',coinbase:true,unconfirmed:false,vout:Array.from({length:count},(_,n)=>({n:String(n),value:String(value),script,address}))};else throw Error('Unexpected fixture URL: '+url);return new Response(JSON.stringify(data));};
 return {vector,address,script,raw,prev,calls,state,fetcher,signWasmBytes:readFileSync(new URL('../../src/pq/qtc-mldsa44-sign.wasm',import.meta.url)),receiveWasmBytes:readFileSync(new URL('../../src/pq/receive-keygen.wasm',import.meta.url))};
}
